"""Generates the thin line-icon vectors for the SystemUI overlay (status bar + quick settings). Run, then rebuild SystemUI overlay."""
import os
D = os.path.expanduser('~/ios-reskin/work/sysui/res/drawable')
os.makedirs(D, exist_ok=True)
ON, OFF = '#FFFFFFFF', '#4DFFFFFF'

def vec(body, size, vp):
    return f'''<?xml version="1.0" encoding="utf-8"?>
<!-- generated by tools/gen_icons.py (design/tokens.md) -->
<vector xmlns:android="http://schemas.android.com/apk/res/android"
    android:width="{size}dp" android:height="{size}dp" android:viewportWidth="{vp}" android:viewportHeight="{vp}">
{body}</vector>
'''
def stroke(path, color, w):
    return f'    <path android:pathData="{path}" android:strokeColor="{color}" android:strokeWidth="{w}" android:strokeLineCap="round" android:strokeLineJoin="round" android:fillColor="#00000000"/>\n'
def fill(path, color):
    return f'    <path android:pathData="{path}" android:fillColor="{color}"/>\n'
def write(name, content):
    open(f'{D}/{name}.xml', 'w').write(content)

def wifi(level, vp, w, size, scale):
    s = scale
    arcs = [(5, 3.21, 3.83), (9, 5.79, 6.89), (13, 8.36, 9.96)]
    cx, cy = 12 * s, 19.5 * s
    b = fill(f'M{cx},{cy} m{-1.7*s},0 a{1.7*s},{1.7*s} 0 1,0 {3.4*s},0 a{1.7*s},{1.7*s} 0 1,0 {-3.4*s},0', ON if level >= 1 else OFF)
    for i, (r, dx, dy) in enumerate(arcs):
        b += stroke(f'M{cx-dx*s:.2f},{cy-dy*s:.2f} A{r*s},{r*s} 0 0 1 {cx+dx*s:.2f},{cy-dy*s:.2f}', ON if level >= i + 2 else OFF, w)
    return vec(b, size, vp)

def cell(level, vp, w, size, scale, slash=False):
    s = scale
    xs, tops = [5, 10, 15, 20], [16, 12, 8, 4]
    b = ''.join(stroke(f'M{xs[i]*s},{20*s} L{xs[i]*s},{tops[i]*s}', ON if level > i else OFF, w) for i in range(4))
    if slash:
        b += stroke(f'M{3*s},{3*s} L{21*s},{21*s}', ON, w * 0.8)
    return vec(b, size, vp)

# status bar (17 dp, 24-unit grid)
for lv in range(5):
    for suf in ('', '_fully'):
        write(f'stat_sys_wifi_signal_{lv}{suf}', wifi(lv, 24, 1.9, 17, 1))
        write(f'stat_sys_signal_{lv}{suf}', cell(lv, 24, 2.8, 17, 1))
# quick settings (48-unit grid)
for lv in range(5):
    for pre in ('ic_qs_wifi_', 'ic_qs_wifi_full_'):
        write(f'{pre}{lv}', wifi(lv, 48, 3.2, 48, 2))
    for pre in ('ic_qs_signal_', 'ic_qs_signal_full_'):
        write(f'{pre}{lv}', cell(lv, 48, 4.4, 48, 2))
write('ic_qs_wifi_disabled', wifi(0, 48, 3.2, 48, 2).replace('</vector>', stroke('M8,8 L40,40', ON, 3.2) + '</vector>'))
write('ic_qs_wifi_disconnected', wifi(0, 48, 3.2, 48, 2))
write('ic_qs_wifi_no_network', wifi(0, 48, 3.2, 48, 2))
write('ic_qs_signal_no_signal', cell(0, 48, 4.4, 48, 2))
write('ic_qs_signal_disabled', cell(0, 48, 4.4, 48, 2, slash=True))
write('ic_qs_data_disabled', cell(0, 48, 4.4, 48, 2, slash=True))
bt = 'M17,17 L31,31 L24,38 L24,10 L31,17 L17,31'
for n, col in (('on', ON), ('connected', ON), ('connecting', ON), ('off', OFF)):
    write(f'ic_qs_bluetooth_{n}', vec(stroke(bt, col, 3.2), 48, 48))
dnd = stroke('M24,24 m-15,0 a15,15 0 1,0 30,0 a15,15 0 1,0 -30,0', ON, 3.2) + stroke('M16,24 L32,24', ON, 3.2)
write('ic_qs_dnd_on', vec(dnd, 48, 48))
write('ic_qs_dnd_on_priority', vec(dnd, 48, 48))
write('ic_qs_dnd_on_total_silence', vec(dnd, 48, 48))
write('ic_qs_dnd_off', vec(dnd.replace(ON, OFF), 48, 48))
print(len(os.listdir(D)), 'icons')

# ---- extra static icons (animated vectors such as torch / rotation / airplane tile are left stock) ----
def sc(v, s): return f'{v*s:.2f}'
def P(pts, s, close=False):
    d = 'M' + ' L'.join(f'{sc(x,s)},{sc(y,s)}' for x, y in pts)
    return d + (' Z' if close else '')
def ring(cx, cy, r, s):
    return f'M{sc(cx-r,s)},{sc(cy,s)} a{sc(r,s)},{sc(r,s)} 0 1,0 {sc(2*r,s)},0 a{sc(r,s)},{sc(r,s)} 0 1,0 {sc(-2*r,s)},0'

def icons(s, vp, size, w, color=ON):
    out = {}
    out['zen'] = stroke(ring(12, 12, 8.5, s), color, w) + stroke(P([(8.5, 12), (15.5, 12)], s), color, w)
    out['sim'] = stroke(P([(7.5, 3.5), (14.5, 3.5), (18, 7), (18, 20.5), (7.5, 20.5)], s, True), color, w)
    out['nosim'] = out['sim'] + stroke(P([(3.5, 3.5), (21, 21)], s), color, w)
    out['alarm'] = (stroke(ring(12, 13, 7.5, s), color, w) + stroke(P([(12, 13), (12, 9)], s), color, w) +
                    stroke(P([(12, 13), (15, 14.5)], s), color, w) + stroke(P([(3.5, 6), (6.5, 3)], s), color, w) +
                    stroke(P([(20.5, 6), (17.5, 3)], s), color, w))
    out['plane'] = stroke(P([(12, 3), (13.8, 9.5), (21, 13.5), (21, 15.5), (13.8, 13.5), (13, 18.5), (15.5, 20.5), (15.5, 21.5), (12, 20.7), (8.5, 21.5), (8.5, 20.5), (11, 18.5), (10.2, 13.5), (3, 15.5), (3, 13.5), (10.2, 9.5)], s, True), color, w)
    out['bt'] = stroke(P([(8.5, 8.5), (15.5, 15.5), (12, 19), (12, 5), (15.5, 8.5), (8.5, 15.5)], s), color, w)
    out['moon'] = stroke(f'M{sc(16.5,s)},{sc(4.5,s)} A{sc(8.5,s)},{sc(8.5,s)} 0 1,0 {sc(19.5,s)},{sc(15.5,s)} A{sc(7,s)},{sc(7,s)} 0 0,1 {sc(16.5,s)},{sc(4.5,s)} Z', color, w)
    cast = stroke(f'M{sc(3.5,s)},{sc(8,s)} V{sc(6.5,s)} A{sc(1.5,s)},{sc(1.5,s)} 0 0 1 {sc(5,s)},{sc(5,s)} H{sc(19,s)} A{sc(1.5,s)},{sc(1.5,s)} 0 0 1 {sc(20.5,s)},{sc(6.5,s)} V{sc(17.5,s)} A{sc(1.5,s)},{sc(1.5,s)} 0 0 1 {sc(19,s)},{sc(19,s)} H{sc(14,s)}', color, w)
    for r in (4, 8, 12):
        cast += stroke(f'M{sc(3.5+r,s)},{sc(19,s)} A{sc(r,s)},{sc(r,s)} 0 0 0 {sc(3.5,s)},{sc(19-r,s)}', color, w)
    out['cast'] = cast
    return out

st = icons(1, 24, 17, 1.9)
write('stat_sys_zen_none', vec(st['zen'], 17, 24)); write('stat_sys_zen_important', vec(st['zen'], 17, 24))
write('stat_sys_no_sims', vec(st['nosim'], 17, 24))
write('stat_sys_alarm', vec(st['alarm'], 17, 24)); write('stat_sys_alarm_dim', vec(icons(1, 24, 17, 1.9, OFF)['alarm'], 17, 24))
write('stat_sys_airplane_mode', vec(st['plane'], 17, 24))
write('stat_sys_data_bluetooth', vec(st['bt'], 17, 24)); write('stat_sys_data_bluetooth_connected', vec(st['bt'], 17, 24))
q = icons(2, 48, 48, 3.2)
write('ic_qs_no_sim', vec(q['nosim'], 48, 48))
write('ic_qs_cast_on', vec(q['cast'], 48, 48)); write('ic_qs_cast_off', vec(icons(2, 48, 48, 3.2, OFF)['cast'], 48, 48))
write('ic_qs_night_display_on', vec(q['moon'], 48, 48)); write('ic_qs_night_display_off', vec(icons(2, 48, 48, 3.2, OFF)['moon'], 48, 48))
print(len(os.listdir(D)), 'icons after extras')

# DND icons shown in the status bar (separate from stat_sys_zen_*)
for n in ('stat_sys_dnd', 'stat_sys_dnd_priority', 'stat_sys_dnd_total_silence'):
    write(n, vec(st['zen'], 17, 24))
